SELECT DISTINCT m.menu_id, m.parent_id, m.menu_name, m.path, m.component, m.`query`, m.visible, m.STATUS, ifnull( m.perms, '' ) AS perms, m.is_frame, m.is_cache, m.menu_type, m.icon, m.order_num, m.create_time FROM tb_special_menu m LEFT JOIN tb_special_role_menu rm ON rm.menu_id = m.menu_id LEFT JOIN tb_special_role_user u ON u.role_id = rm.role_id LEFT JOIN tb_special_role r ON r.role_id = u.role_id WHERE
u.user_id = #{params.userId}
AND u.special_id = #{params.specialId}
AND m.menu_name like concat('%', #{menuName}, '%')
AND m.visible = #{visible}
AND m.status = #{status}
ORDER BY m.parent_id, m.order_num
